<template><DetailSection title="商业口径试算" :grid="false" description="商品实付不含运费，向下取整到分。只调用当前版本的后端预览，不产生订单或资金快照。"><Form :label-width="170"><div class="ui-form-grid"><FormItem label="商品实付（元）"><MoneyInput v-model="product"/></FormItem><FormItem label="运费（元，不入基数）"><MoneyInput v-model="shipping"/></FormItem></div></Form><Button type="primary" :loading="loading" :disabled="product==null||shipping==null" @click="preview">试算当前版本</Button><p v-if="error" class="ui-error">{{error}}</p><div v-if="result" class="ui-result"><p>佣金 {{money(result.commissionCent)}}；商户商品余款 {{money(result.merchantProductCent)}}。</p><p class="ui-meta">{{percent(rule.payload.rateBps)}} · 商品实付不含运费 · 向下到分 · 规则提交 v{{result.revision}}</p></div></DetailSection></template>
<script>import {s1Read} from '@/api/stage1';import {money,percent} from '../display.cjs';import MoneyInput from './MoneyInput';import DetailSection from './DetailSection';export default {components:{MoneyInput,DetailSection},props:{rule:{type:Object,required:true}},data:()=>({product:null,shipping:null,loading:false,error:'',result:null,ticket:0}),watch:{rule(){this.ticket++;this.result=null;}},beforeDestroy(){this.ticket++;},methods:{money,percent,async preview(){const ticket=++this.ticket,id=this.rule.id;this.loading=true;this.error='';this.result=null;try{const value=await s1Read('/commission-rules/'+id+'/preview',{productPaidCent:this.product,shippingCent:this.shipping});if(ticket===this.ticket&&id===this.rule.id)this.result=value;}catch(e){if(ticket===this.ticket)this.error=e.message;}finally{if(ticket===this.ticket)this.loading=false;}}}};</script>
